function tryMine(t){for(let i=0;i<20;i++){const m=mc.mine_block(t,8,64);if(m&&m.mined>0){mc.collect(t,64,8);if(hasWood())return true;}if(hasWood())return true;}return hasWood();}
function tryMoveTo(x,y,z){const tries=[y,y+1,y-1,y+2,y-2,y+3,y-3];for(const ty of tries){const mv=mc.move_to(x,ty,z,30000);if(mv&&mv.at)return mv.at;}return null;}
if(hasWood()){console.log('Wood already held.');}
else{
  let done=false;
  for(const t of LOGS){if(!done){const mv=mc.move_to_block(t,128,60000);if(mv&&mv.block){if(tryMine(t))done=true;}}}
  if(!done){
    let sx=41,sy=66,sz=1;
    for(let step=1;step<=80&&!done;step++){
      const at=tryMoveTo(sx,sy,sz-step*4);
      if(at){sx=at.x;sy=at.y;sz=at.z;}
      const t=findLogType(16);
      if(t){if(tryMine(t))done=true;}
    }
  }
}
if(hasWood()){console.log('Wood collected.');}else{console.log('No wood found.');throw new Error('No wood found.');}
